int insideCount = 0;
for (int i = 0; i < numberOfChecks; ++i) {
    CGALRay ray(CGALPoint(p.x(), p.y(), p.z()), cg3::internal::randomDirection());
    int intersections = tree.number_intersected_primitives(ray);
    if (intersections % 2 != 0) {
        insideCount++;
    }
}
return (insideCount > numberOfChecks / 2);

